import{A as t}from"./aos-8be333ee.js";import{_ as i,b as d,o as s,c as e,a as o}from"./index-79be049c.js";const v="/resume/assets/p03-efc699d0.jpg";const l={class:"autobiography"},_={__name:"Autobiography",setup(c){return d(()=>{t.init()}),(f,a)=>(s(),e("div",l,a[0]||(a[0]=[o('<h1 class="auto_title" data-aos="fade-left" data-aos-duration="1000" data-v-f7801252>AUTOBIOGRAPHY</h1><div class="auto_mains" data-v-f7801252><div class="auto_title_main" data-aos="fade-up" data-aos-duration="2000" data-v-f7801252><div class="title_wrap" data-v-f7801252><div class="title_line1" data-v-f7801252></div><h2 class="auto_main_title" data-v-f7801252>關於我</h2><div class="title_line2" data-v-f7801252></div></div><h4 class="auto_main_tec" data-v-f7801252>我是黃意晴，大學就讀文化大學廣告系，主要是學習廣告行銷企劃的撰寫，畢業後從事影音行銷有五年左右的經驗，參與過很多不同的產業，像是新媒體業、服飾品牌、經紀公司、牙醫、政治、Youtube等，從企劃、拍攝到剪輯都有很豐富的工作經驗。影音產業很需要團隊合作、注意流行趨勢和學習技術，這也是我擅長的地方，也能在緊湊的排程裡完成工作。</h4></div><div class="auto_title_main" data-aos="fade-up" data-aos-duration="2000" data-aos-delay="300" data-v-f7801252><div class="title_wrap" data-v-f7801252><div class="title_line1" data-v-f7801252></div><h2 class="auto_main_title" data-v-f7801252>轉職契機</h2><div class="title_line2" data-v-f7801252></div></div><h4 class="auto_main_tec" data-v-f7801252>因為想要架設作品集網站而使用了wix，因此讓我對網頁設計有興趣，在上網收集資料後，對前端工程師的工作有憧憬，所以報名了Tibame的前端工程師課程。為期四個月的扎實訓練，並用所學的技術完成個人專題-攝影工作室網站，運用HTML、CSS和JS架設自己的作品集網站，可以讓作品集更有設計感的呈現。</h4></div><div class="auto_title_main" data-aos="fade-up" data-aos-duration="2000" data-v-f7801252><div class="title_wrap" data-v-f7801252><div class="title_line1" data-v-f7801252></div><h2 class="auto_main_title" data-v-f7801252>專題表現</h2><div class="title_line2" data-v-f7801252></div></div><h4 class="auto_main_tec" data-v-f7801252>在期末團體專題時，我有幸被組員選為組長，負責安排時程和維持組內的氣氛。團體專題是用vue的框架去製作，主題是沈浸式體驗活動，總共有三個主題活動可以讓使用者瀏覽、預約和購買周邊商品，後端則運用php和MySQL做資料庫串接，最後由我整合組員各自做的部分，並打包上傳server，完成網站的製作。</h4></div><div class="auto_title_main" data-aos="fade-up" data-aos-duration="2000" data-v-f7801252><div class="title_wrap" data-v-f7801252><div class="title_line1" data-v-f7801252></div><h2 class="auto_main_title" data-v-f7801252>個人特質</h2><div class="title_line2" data-v-f7801252></div></div><h4 class="auto_main_tec" data-v-f7801252>我的主管和團隊過去最認可我的是高效解決問題的能力，每當面對新挑戰，我會優先查找資料並主動提出可行解決方案，減少團隊負擔。<br data-v-f7801252> 我擁有很強的學習力，從以前自學拍片和剪片變成主業，到現在轉職學習前端的技術，只要遇到喜歡的事就會努力學，再加上在影音業磨出來的抗壓性和毅力，相信未來可以運用前端相關的技術，並結合舊有的工作經驗，在公司內與同事一起完成專案，並在閒暇時間持續學習新的程式技術，能夠有更好地發揮。</h4></div></div><img class="autobiography_photo" src="'+v+'" alt="" data-aos="fade-up" data-aos-duration="2000" data-v-f7801252>',3)])))}},r=i(_,[["__scopeId","data-v-f7801252"]]);export{r as default};
